function basename(pathText) {
  let lastSlash = -1;
  for (let index = 0; index < pathText.length; index += 1) {
    const char = pathText[index];
    if (char === '/' || char === '\\') {
      lastSlash = index;
    }
  }
  if (lastSlash === -1) {
    return pathText;
  }
  return pathText.slice(lastSlash + 1);
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A`;
}

function help(programName) {
  return `${usage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n`;
}

function looksLikeNegativeNumber(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  const first = token[1];
  return (first >= '0' && first <= '9') || first === '.';
}

export function parseCommandLine(argv, scriptPath = 'test16.mjs') {
  const programName = basename(scriptPath);
  let value;
  let hasValue = false;
  const extras = [];
  let index = 0;

  while (index < argv.length) {
    const arg = argv[index];

    if (arg === '-h' || arg === '--help') {
      return {
        ok: true,
        help: true,
        output: help(programName),
      };
    }

    if (arg === '--') {
      for (let extraIndex = index + 1; extraIndex < argv.length; extraIndex += 1) {
        extras.push(argv[extraIndex]);
      }
      break;
    }

    if (arg === '--a') {
      const next = index + 1 < argv.length ? argv[index + 1] : undefined;
      if (
        next === undefined ||
        next === '--' ||
        ((next === '-h' || next === '--help' || next.startsWith('--')) && !looksLikeNegativeNumber(next))
      ) {
        return {
          ok: false,
          code: 2,
          output:
            `${usage(programName)}\n` +
            `${programName}: error: argument --a: expected one argument\n`,
        };
      }
      value = next;
      hasValue = true;
      index += 2;
      continue;
    }

    if (arg.startsWith('--a=')) {
      value = arg.slice(4);
      hasValue = true;
      index += 1;
      continue;
    }

    extras.push(arg);
    index += 1;
  }

  if (!hasValue) {
    return {
      ok: false,
      code: 2,
      output:
        `${usage(programName)}\n` +
        `${programName}: error: the following arguments are required: --a\n`,
    };
  }

  if (extras.length > 0) {
    return {
      ok: false,
      code: 2,
      output:
        `${usage(programName)}\n` +
        `${programName}: error: unrecognized arguments: ${extras.join(' ')}\n`,
    };
  }

  return {
    ok: true,
    help: false,
    value,
  };
}

