        digitsAfter += 1;
      }
      index += 1;
    }
  }
  if (digitsBefore === 0 && digitsAfter === 0) {
    return false;
  }
  if (index < text.length && (text[index] === 'e' || text[index] === 'E')) {
    index += 1;
    if (index < text.length && (text[index] === '+' || text[index] === '-')) {
      index += 1;
    }
    let exponentDigits = 0;
    while (index < text.length && (isDigit(text[index]) || text[index] === '_')) {
      if (isDigit(text[index])) {
        exponentDigits += 1;
      }
      index += 1;
    }
    if (exponentDigits === 0) {
      return false;
    }
  }
  return index === text.length && (digitsAfter > 0 || text.includes('.') || text.includes('e') || text.includes('E'));
}

function parseYamlFloat(text) {
  if (text.length === 0) {
    return null;
  }

  const lower = lowerAscii(removeUnderscores(text));
  if (lower === '.inf' || lower === '+.inf') {
    return Number.POSITIVE_INFINITY;
  }
  if (lower === '-.inf') {
    return Number.NEGATIVE_INFINITY;
  }
  if (lower === '.nan' || lower === '+.nan' || lower === '-.nan') {
    return Number.NaN;
  }

  let sign = 1;
  let body = removeUnderscores(text);
  if (body[0] === '+' || body[0] === '-') {
    sign = body[0] === '-' ? -1 : 1;
    body = body.slice(1);
  }

  if (body.includes(':')) {
    const value = parseSexagesimalFloat(body);
    return value === null ? null : sign * value;
  }

  if (!isDecimalFloat(removeUnderscores(text))) {
    return null;
  }

  const value = Number(removeUnderscores(text));
  return Number.isNaN(value) ? null : value;
}

function parseTimezone(text, start) {
  if (start >= text.length) {
    return { index: start, timezone: '' };
  }
  const char = text[start];
  if (char === 'Z' || char === 'z') {
    return { index: start + 1, timezone: '+00:00' };
  }
  if (char !== '+' && char !== '-') {
    return null;
  }

  const hour = parseDigits(text, start + 1, 1, 2);
  if (hour === null) {
    return null;
  }
  let index = hour.index;
  let minuteValue = 0;
  if (index < text.length && text[index] === ':') {
    const minute = parseDigits(text, index + 1, 2, 2);
    if (minute === null) {
      return null;
    }
    minuteValue = minute.value;
    index = minute.index;
  } else if (index + 2 <= text.length && isDigit(text[index]) && isDigit(text[index + 1])) {
    minuteValue = (text.charCodeAt(index) - 48) * 10 + (text.charCodeAt(index + 1) - 48);
    index += 2;
  }
  if (minuteValue >= 60) {
    return null;
  }
  return {
    index,
    timezone: `${char}${hour.value < 10 ? `0${hour.value}` : `${hour.value}`}:${minuteValue < 10 ? `0${minuteValue}` : `${minuteValue}`}`,
  };
}

function parseYamlTimestamp(text) {
  const dateYear = parseDigits(text, 0, 4, 4);
  if (dateYear === null || dateYear.index >= text.length || text[dateYear.index] !== '-') {
    return null;
  }
  const dateMonth = parseDigits(text, dateYear.index + 1, 1, 2);
  if (dateMonth === null || dateMonth.index >= text.length || text[dateMonth.index] !== '-') {
    return null;
  }
  const dateDay = parseDigits(text, dateMonth.index + 1, 1, 2);
  if (dateDay === null) {
    return null;
  }
  let index = dateDay.index;
  if (index === text.length) {
    return new YamlTimestamp({
      year: dateYear.value,
      month: dateMonth.value,
      day: dateDay.value,
      hasTime: false,
    });
  }

  const separator = text[index];
  if (separator !== 'T' && separator !== 't' && separator !== ' ') {
    return null;
  }
  const hour = parseDigits(text, index + 1, 1, 2);
  if (hour === null || hour.index >= text.length || text[hour.index] !== ':') {
    return null;
  }
  const minute = parseDigits(text, hour.index + 1, 1, 2);
  if (minute === null || minute.index >= text.length || text[minute.index] !== ':') {
    return null;
  }
  const second = parseDigits(text, minute.index + 1, 1, 2);
  if (second === null) {
    return null;
  }
  index = second.index;
  let microsecond = 0;
  if (index < text.length && text[index] === '.') {
    index += 1;
    const fractionStart = index;
    let digits = '';
    while (index < text.length && isDigit(text[index])) {
      digits += text[index];
      index += 1;
    }
    if (digits.length === 0) {
      return null;
    }
    while (digits.length < 6) {
      digits += '0';
    }
    if (digits.length > 6) {
      digits = digits.slice(0, 6);
    }
    microsecond = Number(digits);
    if (!Number.isInteger(microsecond) || fractionStart === index) {
      return null;
    }
  }
  const timezone = parseTimezone(text, index);
  if (timezone === null) {
    return null;
  }
  if (timezone.index !== text.length) {
    return null;
  }

  return new YamlTimestamp({
    year: dateYear.value,
    month: dateMonth.value,
    day: dateDay.value,
    hasTime: true,
    hour: hour.value,
    minute: minute.value,
    second: second.value,
    microsecond,
    timezone: timezone.timezone,
  });
}

function resolvePlainScalar(text) {
  if (text.length === 0) {
    return null;
  }

  const lower = lowerAscii(text);
  if (lower === '~' || lower === 'null') {
    return null;
  }
  if (
    lower === 'y' ||
    lower === 'yes' ||
    lower === 'true' ||
    lower === 'on'
  ) {
    return true;
  }
  if (
    lower === 'n' ||
    lower === 'no' ||
    lower === 'false' ||
    lower === 'off'
  ) {
    return false;
  }

  const integerValue = parseYamlInteger(text);
  if (integerValue !== null) {
    return integerValue;
  }

  const floatValue = parseYamlFloat(text);
  if (floatValue !== null) {
    return floatValue;
  }

  const timestamp = parseYamlTimestamp(text);
  if (timestamp !== null) {
    return timestamp;
  }

  return text;
}

function stringifyScalarValue(value) {
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (typeof value === 'number') {
    if (Number.isNaN(value)) {
      return '.nan';
    }
    if (value === Number.POSITIVE_INFINITY) {
      return '.inf';
    }
    if (value === Number.NEGATIVE_INFINITY) {
      return '-.inf';
    }
    return String(value);
  }
  if (typeof value === 'string') {
    return value;
  }
  if (value instanceof YamlTimestamp) {
    return value.toDumpString();
  }
  throw new YamlError('unsupported tagged scalar');
}

function applyExplicitTag(tag, value, originalText = null) {
  const normalized = normalizeTag(tag);
  if (normalized === null) {
    return value;
  }

  if (normalized === 'tag:yaml.org,2002:str') {
    return originalText === null ? stringifyScalarValue(value) : originalText;
  }
  if (normalized === 'tag:yaml.org,2002:int') {
    const source = originalText === null ? stringifyScalarValue(value) : originalText;
    const parsed = parseYamlInteger(source);
    if (parsed === null) {
      throw new YamlError(`cannot construct integer from ${source}`);
    }
    return parsed;
  }
  if (normalized === 'tag:yaml.org,2002:float') {
    const source = originalText === null ? stringifyScalarValue(value) : originalText;
    const parsed = parseYamlFloat(source);
    if (parsed === null) {
      throw new YamlError(`cannot construct float from ${source}`);
    }
    return parsed;
  }
  if (normalized === 'tag:yaml.org,2002:bool') {
    const source = originalText === null ? stringifyScalarValue(value) : originalText;
    const lower = lowerAscii(source);
    if (lower === 'true' || lower === 'yes' || lower === 'on' || lower === 'y') {
      return true;
    }
    if (lower === 'false' || lower === 'no' || lower === 'off' || lower === 'n') {
      return false;
    }
    throw new YamlError(`cannot construct boolean from ${source}`);
  }
  if (normalized === 'tag:yaml.org,2002:null') {
    return null;
  }
  if (normalized === 'tag:yaml.org,2002:timestamp') {
    const source = originalText === null ? stringifyScalarValue(value) : originalText;
    const parsed = parseYamlTimestamp(source);
    if (parsed === null) {
      throw new YamlError(`cannot construct timestamp from ${source}`);
    }
    return parsed;
  }
  if (normalized === 'tag:yaml.org,2002:seq') {
    if (!Array.isArray(value)) {
      throw new YamlError('tag !!seq requires a sequence');
    }
    return value;
  }
  if (normalized === 'tag:yaml.org,2002:map') {
    if (!(value instanceof Map)) {
      throw new YamlError('tag !!map requires a mapping');
    }
    return value;
  }

  throw new YamlError(`could not determine a constructor for the tag '${tag}'`);
}

function readAnchorOrTagToken(text, start) {
  if (start >= text.length) {
    return null;
  }
  if (text[start] === '!') {
    if (start + 1 < text.length && text[start + 1] === '<') {
      let index = start + 2;
      while (index < text.length && text[index] !== '>') {
        index += 1;
      }
      if (index >= text.length) {
        throw new YamlError('unterminated tag token');
      }
      return {
        token: text.slice(start, index + 1),
        index: index + 1,
      };
    }
  }
  let index = start;
  while (index < text.length) {
    const char = text[index];
    if (
      isSpace(char) ||
      char === ',' ||
      char === '[' ||
      char === ']' ||
      char === '{' ||
      char === '}' ||
      char === '#'
    ) {
      break;
    }
    index += 1;
  }
  if (index === start) {
    return null;
  }
  return {
    token: text.slice(start, index),
    index,
  };
}

function parseProperties(text, start) {
  let index = start;
  let anchor = null;
  let tag = null;

  while (index < text.length) {
    index = findFirstNonSpace(text, index);
    if (index >= text.length) {
      break;
    }
    const char = text[index];
    if (char === '&') {
      const anchorToken = readAnchorOrTagToken(text, index + 1);
      if (anchorToken === null || anchorToken.token.length === 0) {
        throw new YamlError('invalid anchor');
      }
      anchor = anchorToken.token;
      index = anchorToken.index;
      continue;
    }
    if (char === '!') {
      const tagToken = readAnchorOrTagToken(text, index);
      if (tagToken === null) {
        throw new YamlError('invalid tag');
      }
      tag = tagToken.token;
      index = tagToken.index;
      continue;
    }
    break;
  }

  return { anchor, tag, index };
}

function parseSingleQuoted(text, start) {
  let index = start + 1;
  let value = '';
  while (index < text.length) {
    const char = text[index];
    if (char === '\'') {
      if (index + 1 < text.length && text[index + 1] === '\'') {
        value += '\'';
        index += 2;
        continue;
      }
      return { value, index: index + 1 };
    }
    value += char;
    index += 1;
  }
  throw new YamlError('unterminated single-quoted scalar');
}

function parseDoubleQuoted(text, start) {
  let index = start + 1;
  let value = '';
  while (index < text.length) {
    const char = text[index];
    if (char === '"') {
      return { value, index: index + 1 };
    }
    if (char === '\\') {
      if (index + 1 >= text.length) {
        throw new YamlError('unterminated escape sequence');
      }
      const escape = text[index + 1];
      if (escape === '0') {
        value += '\0';
        index += 2;
        continue;
      }
      if (escape === 'a') {
        value += '\x07';
        index += 2;
        continue;
      }
      if (escape === 'b') {
        value += '\b';
        index += 2;
        continue;
      }
      if (escape === 't' || escape === '\t') {
        value += '\t';
        index += 2;
        continue;
      }
      if (escape === 'n') {
        value += '\n';
        index += 2;
        continue;
      }
      if (escape === 'v') {
        value += '\v';
        index += 2;
        continue;
      }
      if (escape === 'f') {
        value += '\f';
        index += 2;
        continue;
      }
      if (escape === 'r') {
        value += '\r';
        index += 2;
        continue;
      }
      if (escape === 'e') {
        value += '\x1B';
        index += 2;
        continue;
      }
      if (escape === ' ') {
        value += ' ';
        index += 2;
        continue;
      }
      if (escape === '"') {
        value += '"';
        index += 2;
        continue;
      }
      if (escape === '/') {
        value += '/';
        index += 2;
        continue;
      }
      if (escape === '\\') {
        value += '\\';
        index += 2;
        continue;
      }
      if (escape === 'N') {
        value += '\u0085';
        index += 2;
        continue;
      }
      if (escape === '_') {
        value += '\u00A0';
        index += 2;
        continue;
      }
      if (escape === 'L') {
        value += '\u2028';
        index += 2;
        continue;
      }
      if (escape === 'P') {
        value += '\u2029';
        index += 2;
        continue;
      }
      if (escape === 'x' || escape === 'u' || escape === 'U') {
        const width = escape === 'x' ? 2 : escape === 'u' ? 4 : 8;
        const parsed = parseHexDigits(text, index + 2, width);
        if (parsed === null) {
          throw new YamlError('invalid hexadecimal escape');
        }
        value += String.fromCodePoint(parsed.value);
        index = parsed.index;
        continue;
      }
    }
    value += char;
    index += 1;
  }
  throw new YamlError('unterminated double-quoted scalar');
}

function foldLines(lines) {
  if (lines.length === 0) {
    return '';
  }
  let result = '';
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (index === 0) {
      result += line;
      continue;
    }
    const previous = lines[index - 1];
    const currentBlank = line.length === 0;
    const previousBlank = previous.length === 0;
    const currentIndented = line.length > 0 && line[0] === ' ';
    const previousIndented = previous.length > 0 && previous[0] === ' ';
    if (previousBlank || currentBlank || previousIndented || currentIndented) {
      result += '\n';
    } else {
      result += ' ';
    }
    result += line;
  }
  return result;
}

class InlineReader {
  constructor(text, anchors) {
    this.text = text;
    this.index = 0;
    this.anchors = anchors;
  }

  skipSpaces() {
    this.index = findFirstNonSpace(this.text, this.index);
  }

  peek() {
    return this.index < this.text.length ? this.text[this.index] : '';
  }

  parseNode(stopAtColon = false) {
    this.skipSpaces();
    const properties = parseProperties(this.text, this.index);
    this.index = findFirstNonSpace(this.text, properties.index);
    const char = this.peek();
    if (char === '*') {
      this.index += 1;
      const alias = readAnchorOrTagToken(this.text, this.index);
      if (alias === null || !this.anchors.has(alias.token)) {
        throw new YamlError(`found undefined alias '${alias === null ? '' : alias.token}'`);
      }
      this.index = alias.index;
      return this.finalize(this.anchors.get(alias.token), properties, null);
    }
    if (char === '[') {
      const value = this.parseSequence();
      return this.finalize(value, properties, null);
    }
    if (char === '{') {
      const value = this.parseMapping();
      return this.finalize(value, properties, null);
    }
    if (char === '\'') {
      const parsed = parseSingleQuoted(this.text, this.index);
      this.index = parsed.index;
      return this.finalize(parsed.value, properties, parsed.value);
    }
    if (char === '"') {
      const parsed = parseDoubleQuoted(this.text, this.index);
      this.index = parsed.index;
      return this.finalize(parsed.value, properties, parsed.value);
    }
    const parsed = this.parsePlainScalar(stopAtColon);
    return this.finalize(resolvePlainScalar(parsed), properties, parsed);
  }

  finalize(value, properties, originalText) {
    const tagged = applyExplicitTag(properties.tag, value, originalText);
    if (properties.anchor !== null) {
      this.anchors.set(properties.anchor, tagged);
    }
    return tagged;
  }

  parsePlainScalar(stopAtColon) {
    const start = this.index;
    let singleQuoted = false;
    let doubleQuoted = false;
    let flowDepth = 0;

    while (this.index < this.text.length) {
      const char = this.text[this.index];
      if (singleQuoted) {
        if (char === '\'') {
          if (this.index + 1 < this.text.length && this.text[this.index + 1] === '\'') {
            this.index += 2;
            continue;
          }
          singleQuoted = false;
        }
        this.index += 1;
        continue;
      }
      if (doubleQuoted) {
        if (char === '\\') {
          this.index += 2;
          continue;
        }
        if (char === '"') {
          doubleQuoted = false;
        }
        this.index += 1;
        continue;
      }
      if (char === '\'') {
        singleQuoted = true;
        this.index += 1;
        continue;
      }
      if (char === '"') {
        doubleQuoted = true;
        this.index += 1;
        continue;
      }
      if (char === '[' || char === '{') {
        flowDepth += 1;
        this.index += 1;
        continue;
      }
      if (char === ']' || char === '}') {
        if (flowDepth === 0) {
          break;
        }
        flowDepth -= 1;
        this.index += 1;
        continue;
      }
      if (flowDepth === 0) {
        if (char === ',' || char === '#') {
          break;
        }
        if (stopAtColon && char === ':') {
          break;
        }
      }
      this.index += 1;
    }

    let end = this.index;
    while (end > start && isSpace(this.text[end - 1])) {
      end -= 1;
    }
    return this.text.slice(start, end);
  }

  parseSequence() {
    const sequence = [];
    this.index += 1;
    while (true) {
      this.skipSpaces();
      if (this.peek() === ']') {
        this.index += 1;
        return sequence;
      }
      const value = this.parseNode(false);
      sequence.push(value);
      this.skipSpaces();
      if (this.peek() === ',') {
        this.index += 1;
        continue;
      }
      if (this.peek() === ']') {
        this.index += 1;
        return sequence;
      }
      throw new YamlError('expected comma or closing bracket in flow sequence');
    }
  }

  parseMapping() {
    const mapping = new Map();
    this.index += 1;
    while (true) {
      this.skipSpaces();
      if (this.peek() === '}') {
        this.index += 1;
        return mapping;
      }
      const key = this.parseNode(true);
      this.skipSpaces();
      if (this.peek() !== ':') {
        throw new YamlError('expected colon in flow mapping');
      }
      this.index += 1;
      const value = this.parseNode(false);
      mapping.set(key, value);
      this.skipSpaces();
      if (this.peek() === ',') {
        this.index += 1;
        continue;
      }
      if (this.peek() === '}') {
        this.index += 1;
        return mapping;
      }
      throw new YamlError('expected comma or closing brace in flow mapping');
    }
  }
}

class YamlParser {
  constructor(source) {
    this.lines = splitLines(source);
    this.index = 0;
    this.anchors = new Map();
  }

  lineAt(index) {
    if (index >= this.lines.length) {
      return null;
    }
    const line = this.lines[index];
    return {
      text: line.text,
      hasBreak: line.hasBreak,
      indent: countIndent(line.text),
    };
  }

  skipBlankLines() {
    while (this.index < this.lines.length) {
      const line = this.lineAt(this.index);
      if (!isBlankOrComment(line.text)) {
        break;
      }
      this.index += 1;
    }
  }

  parse() {
    this.skipBlankLines();
    if (this.index >= this.lines.length) {
      return null;
    }

    let line = this.lineAt(this.index);
    const firstContent = sliceWithoutComment(line.text, line.indent);
    if (firstContent === '---') {
      this.index += 1;
      this.skipBlankLines();
      if (this.index >= this.lines.length) {
        return null;
      }
      line = this.lineAt(this.index);
    }

    const value = this.parseNodeAtRoot();
    this.skipBlankLines();
    if (this.index < this.lines.length) {
      const extra = sliceWithoutComment(this.lineAt(this.index).text, this.lineAt(this.index).indent);
      if (extra === '...') {
        this.index += 1;
        this.skipBlankLines();
      } else {
        throw new YamlError('expected a single document in the stream');
      }
    }
    this.skipBlankLines();
    if (this.index < this.lines.length) {
      throw new YamlError('expected a single document in the stream');
    }
    return value;
  }

  parseNodeAtRoot() {
    this.skipBlankLines();
    const line = this.lineAt(this.index);
    if (line === null) {
      return undefined;
    }
    if (isSequenceEntry(line.text, line.indent)) {
      return this.parseBlockSequence(line.indent);
    }
    if (findTopLevelColon(line.text, line.indent) !== -1) {
      return this.parseBlockMapping(line.indent, null);
    }
    return this.parseStandaloneNode(line.indent, true);
  }

  parseNode(minIndent) {
    this.skipBlankLines();
    const line = this.lineAt(this.index);
    if (line === null || line.indent < minIndent) {
      return undefined;
    }
    if (isSequenceEntry(line.text, line.indent)) {
      return this.parseBlockSequence(line.indent);
    }
    if (findTopLevelColon(line.text, line.indent) !== -1) {
      return this.parseBlockMapping(line.indent, null);
    }
    return this.parseStandaloneNode(line.indent, false);
  }

  parseValueAfterMapping(mappingIndent) {
    this.skipBlankLines();
    const line = this.lineAt(this.index);
    if (line === null) {
      return undefined;
    }
    if (line.indent < mappingIndent) {
      return undefined;
    }
    if (line.indent === mappingIndent && isSequenceEntry(line.text, line.indent)) {
      return this.parseBlockSequence(line.indent);
    }
    if (line.indent <= mappingIndent) {
      return undefined;
    }
    if (findTopLevelColon(line.text, line.indent) !== -1) {
      return this.parseBlockMapping(line.indent, null);
    }
    return this.parseStandaloneNode(line.indent, false);
  }

  parseBlockSequence(indent) {
    const sequence = [];
    while (true) {
      this.skipBlankLines();
      const line = this.lineAt(this.index);
      if (line === null || line.indent !== indent || !isSequenceEntry(line.text, indent)) {
        break;
      }

      let valueStart = indent + 1;
      if (valueStart < line.text.length && line.text[valueStart] === ' ') {
        valueStart = findFirstNonSpace(line.text, valueStart);
      }
      const significant = sliceWithoutComment(line.text, valueStart);
      if (significant.length === 0) {
        this.index += 1;
        const nested = this.parseNode(indent + 1);
        sequence.push(nested === undefined ? null : nested);
        continue;
      }

      const colonIndex = findTopLevelColon(significant, 0);
      if (colonIndex !== -1) {
        const childIndent = valueStart;
        const firstPair = this.parseMappingPair(significant, childIndent, line.indent);
        this.index += 1;
        const mapping = this.parseBlockMapping(childIndent, firstPair);
        sequence.push(mapping);
        continue;
      }

      const value = this.parseInlineOrScalarNode(significant, line.indent, valueStart, false);
      sequence.push(value);
    }
    return sequence;
  }

  parseBlockMapping(indent, firstPair) {
    const mapping = new Map();
    if (firstPair !== null) {
      mapping.set(firstPair.key, firstPair.value);
    }
    while (true) {
      this.skipBlankLines();
      const line = this.lineAt(this.index);
      if (line === null || line.indent !== indent) {
        break;
      }
      if (isSequenceEntry(line.text, indent)) {
        break;
      }
      const significant = sliceWithoutComment(line.text, indent);
      if (significant === '...' || significant === '---') {
        break;
      }
      const colonIndex = findTopLevelColon(significant, 0);
      if (colonIndex === -1) {
        break;
      }
      const pair = this.parseMappingPair(significant, indent, line.indent);
      this.index += 1;
      mapping.set(pair.key, pair.value);
    }
    return mapping;
  }

  parseMappingPair(significantText, mappingIndent, lineIndent) {
    const colonIndex = findTopLevelColon(significantText, 0);
    const keyText = significantText.slice(0, findLastNonSpace(significantText.slice(0, colonIndex)) + 1);
    const keyReader = new InlineReader(keyText, this.anchors);
    const key = keyReader.parseNode(false);
    keyReader.skipSpaces();
    if (keyReader.index !== keyReader.text.length) {
      throw new YamlError('invalid mapping key');
    }

    const remainder = sliceWithoutComment(significantText, colonIndex + 1);
    const remainderStart = findFirstNonSpace(remainder);
    if (remainderStart >= remainder.length) {
      const nextIndex = this.index + 1;
      this.index = nextIndex;
      const nested = this.parseValueAfterMapping(mappingIndent);
      return {
        key,
        value: nested === undefined ? null : nested,
      };
    }

    const valueText = remainder.slice(remainderStart);
    const value = this.parseInlineOrScalarNode(valueText, lineIndent, mappingIndent + 2, false);
    return { key, value };
