  parseStandaloneNode(indent, allowSameIndentContinuation) {
    const line = this.lineAt(this.index);
    const significant = sliceWithoutComment(line.text, indent);
    return this.parseInlineOrScalarNode(significant, indent, indent, allowSameIndentContinuation);
  }

  parseInlineOrScalarNode(text, lineIndent, contentIndent, allowSameIndentContinuation) {
    const properties = parseProperties(text, 0);
    const index = findFirstNonSpace(text, properties.index);
    const content = index >= text.length ? '' : text.slice(index);

    if (content.length === 0) {
      this.index += 1;
      const nested = this.parseNode(contentIndent);
      const value = nested === undefined ? null : nested;
      const tagged = applyExplicitTag(properties.tag, value, null);
      if (properties.anchor !== null) {
        this.anchors.set(properties.anchor, tagged);
      }
