    }

    const first = content[0];
    if (first === '|' || first === '>') {
      const value = this.parseBlockScalar(content, lineIndent);
      const tagged = applyExplicitTag(properties.tag, value, value);
      if (properties.anchor !== null) {
        this.anchors.set(properties.anchor, tagged);
      }
      return tagged;
    }

    if (first === '\'' || first === '"' || first === '[' || first === '{' || first === '*') {
      const reader = new InlineReader(content, this.anchors);
      let value = reader.parseNode(false);
      reader.skipSpaces();
      if (reader.index !== reader.text.length) {
        throw new YamlError('unexpected trailing content');
      }
      value = applyExplicitTag(properties.tag, value, typeof value === 'string' ? value : null);
      if (properties.anchor !== null) {
        this.anchors.set(properties.anchor, value);
      }
      this.index += 1;
      return value;
    }

    const value = this.parsePlainScalar(content, lineIndent, contentIndent, allowSameIndentContinuation);
    const resolved = applyExplicitTag(properties.tag, resolvePlainScalar(value), value);
    if (properties.anchor !== null) {
      this.anchors.set(properties.anchor, resolved);
    }
    return resolved;
  }

  parsePlainScalar(initialText, lineIndent, contentIndent, allowSameIndentContinuation) {
    const lines = [initialText];
    this.index += 1;

    while (this.index < this.lines.length) {
      const line = this.lineAt(this.index);
      if (line === null) {
        break;
      }
      if (isBlankOrComment(line.text)) {
        lines.push('');
        this.index += 1;
        continue;
      }
      if (line.indent < lineIndent) {
        break;
      }
      if (line.indent === lineIndent && !allowSameIndentContinuation) {
        break;
      }
      if (line.indent === lineIndent && (isSequenceEntry(line.text, line.indent) || findTopLevelColon(line.text, line.indent) !== -1)) {
        break;
      }
      if (line.indent > lineIndent && (isSequenceEntry(line.text, line.indent) || findTopLevelColon(line.text, line.indent) !== -1)) {
        break;
      }
      const content = sliceWithoutComment(line.text, line.indent >= contentIndent ? contentIndent : line.indent);
      lines.push(content);
      this.index += 1;
    }

    return foldLines(lines);
  }

  parseBlockScalar(header, parentIndent) {
    let index = 1;
    let chomping = 'clip';
    let indentationIndicator = 0;

    while (index < header.length) {
      const char = header[index];
      if (char === '+' || char === '-') {
        chomping = char === '+' ? 'keep' : 'strip';
        index += 1;
        continue;
      }
      if (isDigit(char)) {
        indentationIndicator = textDigitValue(char);
        index += 1;
        continue;
      }
      if (isSpace(char)) {
        break;
      }
      throw new YamlError('invalid block scalar header');
    }

    this.index += 1;
    let contentIndent = indentationIndicator > 0 ? parentIndent + indentationIndicator : 0;
    if (contentIndent === 0) {
      let lookahead = this.index;
      while (lookahead < this.lines.length) {
        const line = this.lineAt(lookahead);
        if (line === null) {
          break;
        }
        if (isBlankOrComment(line.text)) {
          lookahead += 1;
          continue;
        }
        if (line.indent <= parentIndent) {
          contentIndent = parentIndent + 1;
        } else {
          contentIndent = line.indent;
        }
        break;
      }
      if (contentIndent === 0) {
        contentIndent = parentIndent + 1;
      }
    }

    const lines = [];
    while (this.index < this.lines.length) {
      const line = this.lineAt(this.index);
      if (line === null) {
        break;
      }
      const blank = line.text.length === 0 || findFirstNonSpace(line.text) >= line.text.length;
      if (!blank && line.indent < contentIndent) {
        break;
      }
      if (blank) {
        lines.push('');
        this.index += 1;
        continue;
      }
      lines.push(line.text.slice(contentIndent));
      this.index += 1;
    }

    let result = header[0] === '|' ? lines.join('\n') : foldLines(lines);
    let trailingBlankCount = 0;
    for (let index = lines.length - 1; index >= 0; index -= 1) {
      if (lines[index] !== '') {
        break;
      }
      trailingBlankCount += 1;
    }

    if (chomping === 'strip') {
      while (result.endsWith('\n')) {
        result = result.slice(0, result.length - 1);
      }
      return result;
    }
    if (chomping === 'keep') {
      for (let count = 0; count <= trailingBlankCount; count += 1) {
        result += '\n';
      }
      return result;
    }
    return `${result}\n`;
  }
}

function textDigitValue(char) {
  return char.charCodeAt(0) - 48;
}

export function parseYamlDocument(source) {
  const parser = new YamlParser(source);
  return parser.parse();
}

